import{_ as a,o as s,c as o,e as i}from"./chunks/framework.Cq4gzU1W.js";const m=JSON.parse('{"title":"Motivación","description":"Empezamos a trabajar con ganas","frontmatter":{"title":"Motivación","description":"Empezamos a trabajar con ganas","weight":30},"headers":[],"relativePath":"01_Presentacion/02_Motivacion/index.md","filePath":"01_Presentacion/02_Motivacion/index.md"}'),l={name:"01_Presentacion/02_Motivacion/index.md"};function r(t,e,n,c,d,u){return s(),o("div",null,[...e[0]||(e[0]=[i('<div class="hugo-objetivos"><div class="hugo-objetivos-title"><i class="fas fa-check-circle" aria-hidden="true"></i> Partimos de ...</div><div class="hugo-objetivos-sub">Los profesores partimos de estas premisas</div><ul><li>Vamos a estudiar programación</li><li>Vamos a hacer páginas html y Css</li><li>Nos gusta mucho la programación</li><li>Nos gusta mucho el desarrollo web</li></ul></div><div class="hugo-alert hugo-alert-success"><div class="hugo-alert-title">Nuestro trabajo</div><ul><li>Vamos a programar, generaremos programas</li><li>Los programas que hagamos en el servidor no serán programas interactivos como lo son programas de escritorio</li></ul><blockquote><p>Todos estos conceptos los debatiremos despacio en clase</p></blockquote></div><hr class="hugo-line"><div class="hugo-alert hugo-alert-success"><div class="hugo-alert-title">Marcando nuestro trabajo</div><ul><li>Implementaremos algoritmos (eso siempre)</li></ul><blockquote><p>❓ veremos qué es un algoritmo ❓</p></blockquote><ul><li>El entorno en el cual van a correr las aplicaciones, va a ser en un entorno cliente/servidor</li></ul><blockquote><p>Esto tiene una serie de implicaciones</p></blockquote><ul><li>Vamos a usar un determinado lenguaje de programación.</li></ul><blockquote><p>Necesitamos un lenguaje, pero lo importante es aprender los conceptos (tanto de programación, como de desarrollo web)</p></blockquote><ul><li>Seguimos con un paradigma de lenguajes interpretados de de tipado dinámico fuertemente orientados a las expresiones: <em><strong>PHP</strong></em>.</li></ul><blockquote><p>Analizaremos esto más despacio</p></blockquote></div><div class="hugo-alert hugo-alert-success"><div class="hugo-alert-title">Nuestro trabajo, una parte de un todo</div><span class="hugo-color text-warning">Dependemos de muchos elementos</span><ul><li>Necesitamos la programación del cliente,</li><li>Necesitamos la página dónde embeber nuestro código,</li><li>Necesitmos la red,</li><li>Necesitamos http para transferir nuestras aplicaciones, datos y el resultado de nuestro código,</li><li>Necesitamos un servidor web que residirá en un hosting,</li><li>El código normalmente se ejecutará en una máquina diferente en la que estamos desarrollando, y esto despista un poco. Siempre en un servicio dedicado: El servidor Web</li></ul></div><div class="hugo-alert hugo-alert-success"><div class="hugo-alert-title">Ubicándonos</div><p>Nuestro programa no va a correr necesariamente en el equipo que va a recibir el resultado de su ejecución</p></div><p>===Cómo lo vamos a hacer===</p><div class="hugo-alert hugo-alert-warning"><div class="hugo-alert-title">Fundamental</div><span class="hugo-color text-warning">Muy importante, entender lo qué se hace</span></div><div class="hugo-alert hugo-alert-success"><div class="hugo-alert-title">Puntos fundamentales</div><ul><li>Entender las cosas y dedicarle un tiempo para asimilarlas.</li><li>Todas las que estáis aquí sois inteligentes. La inteligencia es una característica de las personas.</li><li>No todas las personas aprendemos de la misma forma, pero sí que tenemos la facultad de aprender</li><li>Lo que sí que me ha demostrado la experiencia es que A PROGRAMAR SE APRENDE PROGRAMANDO</li><li>No hay prisa y el avance está asegurado si damos pasos seguros</li><li>No debe de haber pausa para llegar a alcanzar nuestro objetivo y ver el temario</li><li>Este temario está pensado para que las empresas os abran las puertas cuando lleguéis a ella.</li><li>El objetivo es <em><strong>aprender disfrutando</strong></em> (y sufriendo un poco je je …).</li><li>Como profesor, he de decir que mi pretensión es daros el pistoletazo de salida, sois vosotros los que en vuestra carrera profesional habréis de <em><strong>llegar lejos</strong></em>,</li><li>Mi misión no es estar en una meta, es encaminaros a vosotros para que lleguéis a ella.</li></ul></div><div class="hugo-alert hugo-alert-success"><div class="hugo-alert-title">Sobre el curso</div><ul><li>Cada tema va a tener un soporte documental que intentará aclarar los contenidos</li><li>Ese soporte se usará para explicar las clases presenciales.</li><li>Cada tema tendrá ejemplos prácticas para poder asimilar los contenidos</li><li>Cada tema intentará tener una práctica o trabajo que debéis entregar/presentar/defender para evaluaros</li></ul></div><div class="hugo-alert hugo-alert-success"><div class="hugo-alert-title">La Asistencia</div><ul><li>Sabéis que es obligatoria</li><li>Podéis faltar de forma justificada, se intentará aportar lo visto para no perder el hilo de las clases</li><li>Venir a clase es una forma de aprender, asentar bases y..... aprobar fácilmente.</li></ul></div>',11)])])}const g=a(l,[["render",r]]);export{m as __pageData,g as default};
